  }
]

prompt_text_ja:
[
  {
    "id": "aerial-artist-red-dress",
    "prompt": "マットブラックの背景の中央に配置された、宙吊りのダイナミックなポーズをとるエアリアルシルクアーティストのプロフェッショナルなスタジオ写真。流れるような[プラチナシルバー]の髪を持ち、落ち着いた集中した表情でわずかに上を見つめる女性アクロバット。頭上の1本の垂直な[白]のエアリアルシルクを右手でしっかりと握り、体を大きく開いたスプリットに近いポーズで宙に浮いている。深いスリットが入った[バーガンディレッド]の流れるようなシルクドレスを纏い、下半身の周りに広がるダイナミックなドレープを描いている。ウエスト、胴体、左足首に巻き付けられた繊細な白いシルク布がアクセント。素足の爪先はピンと伸び、左腕は優雅に外側に伸ばされている。指向性のあるキアロスクーロのスタジオライティングが、肌、布のドレープ、引き締まった筋肉に強いハイライトを作り出し、深い影を落とす。",
    "weight": 1.0,
    "group_id": "image_content"
  },
  {
    "id": "composition_details",
    "prompt": "漆黒の空間にアクロバティックなポーズと舞い上がるドレス全体を収めたミディアムフルショット。垂直な白いシルクが、広がる赤いドレスと対比をなす力強いラインを描く。劇場用スポットライトのようなリムライトが髪や手足の輪郭に柔らかなハロー効果を生み出し、顔と体幹にシャープにピントを合わせる。",
    "weight": 0.8,
    "group_id": "style_and_lighting"
  },
  {
    "id": "fabric_motion",
    "prompt": "宙に舞う布の動きを捉えたハイスピード撮影。ドレスが身体の曲線に呼応して扇状の弧を描く。しっかりと巻き付いた白い布と、自由に流れる赤いサテンのスカートの対比が豊かな陰影を生み出す。",
    "weight": 0.7,
    "group_id": "details"
  },
  {
    "id": "pose_detail",
    "prompt": "ポーズの詳細：引き締まった右腕で垂直のシルクをしっかりと握り、左腕は指先までしなやかに伸ばす。胴体をわずかにひねり、白いシルクが絡む右脚と、爪先までまっすぐ伸びた左脚。",
    "weight": 0.7,
    "group_id": "details"
  }
]

prompt_text_zh:
[
  {
    "id": "aerial-artist-red-dress",
    "prompt": "一张居中构图的专业影棚摄影，背景为哑光深黑虚空，捕捉悬吊空中的杂技绸吊舞者动感姿态。主体是一位留着飘逸[白金色]长发的女艺术家，神情专注宁静，微微仰头望向左上方。她右手高举牢牢抓住单根垂直悬挂的[白色]绸吊缎带，身体呈开合式近一字马的悬空姿态。她身穿一袭开高衩的[深酒红色]缎面流线型长裙，在无形气流中向外剧烈飞扬，在下半身形成大面积的动态色彩弧线。腰部、躯干与左脚踝缠绕着细腻紧致的白色绸吊缎布。赤脚紧绷绷直，左臂优雅向外侧上方舒展。强烈的定向明暗对照法（Chiaroscuro）影棚光照凸显其皮肤高光、布料褶皱质感与清晰紧致的肌肉线条，并投下柔和阴影。",
    "weight": 1.0,
    "group_id": "image_content"
  },
  {
    "id": "composition_details",
    "prompt": "中全景构图，在幽暗空间中完整展示整组杂技姿态与飞舞裙摆。垂直下垂的白绸与翻涌的红色裙裾形成鲜明的线条对比。戏剧聚光灯般的光效在发丝与肢体边缘勾勒出光晕轮廓，焦点精准落在其面部与核心躯干。",
    "weight": 0.8,
    "group_id": "style_and_lighting"
  },
  {
    "id": "fabric_motion",
    "prompt": "高速快门定格布料在半空飞扬的瞬间动态，裙摆如扇面展开呼应身体曲线。深褶展现丰富的光影交错，与紧贴身躯的绷紧白绸形成鲜明材质张力。",
    "weight": 0.7,
    "group_id": "details"
  },
  {
    "id": "pose_detail",
    "prompt": "姿势细节：右手紧握直垂绸缎，手臂肌肉紧绷有力；左手自由舒展，指尖轻盈；躯干微扭；右腿屈膝并缠绕白绸直至脚部；左腿完全伸直并紧绷脚尖。",
    "weight": 0.7,
    "group_id": "details"
  }
]

